create or replace function public.assign_developer_guard_slot_rc1(p_job_id uuid,p_agency_id uuid,p_slot_number integer,p_guard_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_job public.marketplace_jobs;v_guard public.guards;v_slot public.job_guard_slots;v_filled integer;v_required integer; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501';end if;select * into v_job from public.marketplace_jobs where id=p_job_id for update;if v_job.id is null then raise exception 'JOB_NOT_FOUND';end if;if coalesce(v_job.pricing_snapshot->>'developer_test','false')<>'true' then raise exception 'DEVELOPER_TEST_JOB_REQUIRED';end if;if v_job.accepted_agency_id is distinct from p_agency_id then raise exception 'JOB_NOT_OWNED_BY_SELECTED_AGENCY' using errcode='42501';end if;if v_job.status not in('accepted','assigned') then raise exception 'JOB_NOT_ASSIGNABLE';end if;v_required:=greatest(1,least(20,coalesce(v_job.required_guards,1)));if v_required<=1 then raise exception 'USE_SINGLE_GUARD_ASSIGNMENT';end if;if p_slot_number<1 or p_slot_number>v_required then raise exception 'INVALID_GUARD_SLOT';end if;select * into v_guard from public.guards where id=p_guard_id and agency_id=p_agency_id;if v_guard.id is null then raise exception 'GUARD_NOT_IN_SELECTED_AGENCY' using errcode='42501';end if;if coalesce(v_guard.agency_approved,false)=false then raise exception 'GUARD_NOT_AGENCY_APPROVED';end if;if v_job.guard_type='armed' and coalesce(v_guard.armed_qualified,false)=false then raise exception 'ARMED_GUARD_QUALIFICATION_REQUIRED';end if;if v_guard.availability='offline' then raise exception 'GUARD_OFFLINE';end if;perform public.ensure_job_guard_slots(p_job_id);select * into v_slot from public.job_guard_slots where job_id=p_job_id and slot_number=p_slot_number for update;if v_slot.id is null then raise exception 'GUARD_SLOT_NOT_FOUND';end if;if v_slot.guard_id is not null or v_slot.status<>'awaiting_guard' then raise exception 'GUARD_SLOT_ALREADY_FILLED';end if;if exists(select 1 from public.job_guard_slots where job_id=p_job_id and guard_id=p_guard_id and status<>'cancelled') then raise exception 'GUARD_ALREADY_ASSIGNED_TO_JOB';end if;if public.guard_has_schedule_conflict_rc1(p_guard_id,p_job_id) then raise exception 'GUARD_SCHEDULE_CONFLICT';end if;delete from public.guard_slot_mission_state where slot_id=v_slot.id;update public.job_guard_slots set guard_id=p_guard_id,status='offered',offered_at=now(),accepted_at=null,declined_at=null,route_started_at=null,arrived_at=null,completed_at=null,updated_at=now() where id=v_slot.id;update public.marketplace_jobs set status='assigned',updated_at=now() where id=p_job_id;select count(*) into v_filled from public.job_guard_slots where job_id=p_job_id and guard_id is not null and status<>'cancelled';insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),'guard_staffing_slot_offered',jsonb_build_object('agency_id',p_agency_id,'guard_id',p_guard_id,'slot_number',p_slot_number,'filled_slots',v_filled,'required_guards',v_required,'developer_test',true,'source','developer_live_account_test'));return jsonb_build_object('success',true,'job_id',p_job_id,'guard_id',p_guard_id,'slot_number',p_slot_number,'filled_slots',v_filled,'required_guards',v_required,'status','offered');end $$;
revoke all on function public.assign_developer_guard_slot_rc1(uuid,uuid,integer,uuid) from public,anon;
grant execute on function public.assign_developer_guard_slot_rc1(uuid,uuid,integer,uuid) to authenticated,service_role;
